    "/v1/projects/{projectId}/environments/{environment}/logs/search": {
      get: {
        tags: ["Project Compute"], operationId: "searchProjectLogs",
        summary: "Structured search across the log sources that have a read route",
        description: "Since `2.55.0`. This is deliberately **not** SQL over the logs. Every log-like row of QKERN lives in the control plane, where the rows of all organizations share the same tables; an arbitrary query surface over them would rest, for every row, on a single policy. The console SQL editor runs against the project database, not the control plane, and that stays so. Instead this route fans out to the read paths that already exist for three sources and merges them into one list ordered newest first, with source and identifier as tie-breakers so the same search twice yields the same page. Each source is entered through its own existing door and its own capability: auth/admin/audit with `project_auth_admin`, compute/invocations with `project_compute_admin`, storage/objects with `project_storage_admin`. No new read surface is created: a caller who may not read a source sees it reported as not reachable while the others stay usable. Not reachable at all, and named as such in the answer: webhook deliveries (readable only per webhook), usage series (aggregated buckets, not events), cron occurrences (reconstructed per request), function container output (never stored) and the Postgres, pooler, realtime and API gateway logs (no backend). Any unknown parameter, any repeated parameter and any typed filter without its source are a 400 before any service is touched.",
        security: [{ sessionCookie: [] }],
        parameters: [
          ...projectAuthScopeParameters,
          { name: "sources", in: "query", required: false, schema: { type: "string", pattern: "^(auth_audit|function_invocations|storage_objects)(,(auth_audit|function_invocations|storage_objects))*$" }, description: "Comma-separated subset; the answer orders them by the fixed list, not by the input. Default: all three." },
          { name: "from", in: "query", required: false, schema: { type: "string", format: "date-time" }, description: "Start of the half-open range; counted in." },
          { name: "to", in: "query", required: false, schema: { type: "string", format: "date-time" }, description: "End of the half-open range; not counted in." },
          { name: "limit", in: "query", required: false, schema: { type: "integer", minimum: 1, maximum: 100, default: 50 } },
          { name: "before", in: "query", required: false, schema: { type: "string" }, description: "The nextCursor of the previous answer. It marks a place in the total order, not a point in time, so two entries of the same microsecond are neither skipped nor repeated." },
          { name: "authStatus", in: "query", required: false, schema: { type: "string", enum: ["succeeded", "failed"] }, description: "Typed filter of auth_audit." },
          { name: "authActor", in: "query", required: false, schema: { type: "string", enum: ["app_user", "admin", "system"] }, description: "Typed filter of auth_audit." },
          { name: "outcome", in: "query", required: false, schema: { type: "string", enum: ["completed", "failed"] }, description: "Typed filter of function_invocations." },
          { name: "objectStatus", in: "query", required: false, schema: { type: "string", enum: ["quarantined", "clean", "infected"] }, description: "Typed filter of storage_objects." },
        ],
        responses: { "200": { description: "One merged page with a report per source", content: { "application/json": { schema: { $ref: "#/components/schemas/ProjectLogSearchResponse" } } } }, "400": { $ref: "#/components/responses/BadRequest" }, "401": { $ref: "#/components/responses/Unauthorized" }, "503": { description: "No connection was available for the request" } },
      },
    },
