      ProjectAuthReturnTargetsEnvelope: { type: "object", additionalProperties: false, required: ["data"], properties: { data: { $ref: "#/components/schemas/ProjectAuthReturnTargets" } } },
      ProjectAuthReturnTargetRejection: { type: "object", additionalProperties: false, required: ["error"], properties: { error: { type: "string" }, reason: { type: "string", enum: ["not_a_string", "empty", "too_long", "wildcard", "not_a_url", "not_an_origin", "insecure_scheme", "carries_credentials", "outside_outer_bound", "too_many"], description: "A stable key; the console translates it." }, value: { type: "string", maxLength: 255, description: "The entry that was refused." } } },
