      ProjectAuthRateLimits: { type: "object", additionalProperties: false, required: ["limits", "defaults", "bounds", "kinds", "configured", "updatedAt"], properties: { limits: { $ref: "#/components/schemas/ProjectAuthRateLimitSet" }, defaults: { $ref: "#/components/schemas/ProjectAuthRateLimitSet" }, bounds: { type: "object", additionalProperties: false, required: ["max", "windowSeconds"], properties: { max: { type: "object", additionalProperties: false, required: ["min", "max"], properties: { min: { type: "integer" }, max: { type: "integer" } } }, windowSeconds: { type: "object", additionalProperties: false, required: ["min", "max"], properties: { min: { type: "integer" }, max: { type: "integer" } } } } }, kinds: { type: "array", items: { type: "string", enum: ["sign_in", "mail", "refresh"] } }, configured: { type: "boolean", description: "False while the environment never stored a setting; the defaults then apply." }, updatedAt: { type: ["string", "null"], format: "date-time" } } },
      ProjectAuthRateLimitsEnvelope: { type: "object", additionalProperties: false, required: ["data"], properties: { data: { $ref: "#/components/schemas/ProjectAuthRateLimits" } } },
      ProjectAuthRateLimitRejection: { type: "object", additionalProperties: false, required: ["error"], properties: { error: { type: "string" }, reason: { type: "string", enum: ["not_an_object", "unknown_kind", "missing_kind", "max_not_an_integer", "max_out_of_range", "window_not_an_integer", "window_out_of_range"], description: "A stable key; the console translates it." }, field: { type: "string", maxLength: 40, description: "The kind that was refused." } } },
      ProjectAuthPasswordProtectionSetting: { type: "object", additionalProperties: false, required: ["leakedPasswordCheck", "minLength", "notice"], properties: { leakedPasswordCheck: { type: "boolean", description: "Whether newly chosen passwords are checked against the loaded list of known leaked passwords." }, minLength: { type: "integer", minimum: 12, maximum: 128, description: "The length from which a password is accepted. Never below 12, which the service demands regardless." }, notice: { type: "string", enum: ["named", "generic"], description: "named lets a refusal say that the password appears in a known leak; generic says only that it does not meet the policy. Neither says how often or from where." } } },
      ProjectAuthLeakList: { type: "object", additionalProperties: false, required: ["source", "algorithm", "prefixLength", "entries", "builtInEntries", "builtInSource"], properties: { source: { type: "string", enum: ["built_in", "file"] }, algorithm: { type: "string", enum: ["sha1", "sha256"] }, prefixLength: { type: "integer", minimum: 16, maximum: 64, description: "How many hex characters each entry carries; 40 or 64 means a full digest." }, entries: { type: "integer" }, builtInEntries: { type: "integer" }, builtInSource: { type: "string", description: "The named source of the built-in list." } }, description: "What may be said about the loaded list. Never a file path and never an entry." },
      ProjectAuthPasswordProtection: { type: "object", additionalProperties: false, required: ["protection", "defaults", "bounds", "notices", "list", "configured", "updatedAt"], properties: { protection: { $ref: "#/components/schemas/ProjectAuthPasswordProtectionSetting" }, defaults: { $ref: "#/components/schemas/ProjectAuthPasswordProtectionSetting" }, bounds: { type: "object", additionalProperties: false, required: ["minLength"], properties: { minLength: { type: "object", additionalProperties: false, required: ["min", "max"], properties: { min: { type: "integer" }, max: { type: "integer" } } } } }, notices: { type: "array", items: { type: "string", enum: ["named", "generic"] } }, list: { $ref: "#/components/schemas/ProjectAuthLeakList" }, configured: { type: "boolean", description: "False while the environment never stored a setting; the defaults then apply and the check is off." }, updatedAt: { type: ["string", "null"], format: "date-time" } } },
      ProjectAuthPasswordProtectionEnvelope: { type: "object", additionalProperties: false, required: ["data"], properties: { data: { $ref: "#/components/schemas/ProjectAuthPasswordProtection" } } },
